/// <summary>
/// DP class for TO Manifest DangerousGoods report
/// </summary>
[SrsReportParameterAttribute(classStr(METCommonReportContract))]
public class METDangerousGoodsManifestDP extends SrsReportDataProviderPreProcessTempDB
{
    METDangerousGoodsManifestTmp metDangerousGoodsManifestTmp;
    METDangerousGoodsManifestLineTmp metDangerousGoodsManifestLineTmp;
    RecordInsertList lineList;
    METCommonReportContract             dangerouseContract;
    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// Get METDangerousGoodsManifestTmp
/// </summary>
/// <returns>METDangerousGoodsManifestTmp</returns>
[SrsReportDataSetAttribute(tableStr(METDangerousGoodsManifestTmp))]
public METDangerousGoodsManifestTmp getMETDangerousGoodsManifestTmp()
{
    select metDangerousGoodsManifestTmp;
    return metDangerousGoodsManifestTmp;
}

/// <summary>
/// Get METDangerousGoodsManifestLineTmp
/// </summary>
/// <returns>METDangerousGoodsManifestLineTmp</returns>
[SrsReportDataSetAttribute(tableStr(METDangerousGoodsManifestLineTmp))]
public METDangerousGoodsManifestLineTmp getMETDangerousGoodsManifestLineTmp()
{
    select metDangerousGoodsManifestLineTmp;
    return metDangerousGoodsManifestLineTmp;
}

/// <summary>
/// Report business logic
/// </summary>
public void processReport()
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
    InventTable inventTable;
    Qty sumOfItemUnit;
    int countOfStop;

    dangerouseContract = this.parmDataContract();

    lineList = new RecordInsertList(tableNum(METDangerousGoodsManifestLineTmp), true, true, true, true, true, metDangerousGoodsManifestLineTmp);

    select firstonly ToWarehouse, Route, RouteStopNum, ShipmentId from metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == dangerouseContract.parmRecId();

    if (metSalesOrderShipmentLoadHeader)
    {
        this.insertHeaderData(metSalesOrderShipmentLoadHeader);
    }

    while select  ItemId, Quantity, RecId, LineNum, OrderNum, InventTransId from metSalesOrderShipmentLoadLines
        join RecId, RouteStopNum, ShipmentId from metSalesOrderShipmentLoadHeader
        where  metSalesOrderShipmentLoadLines.shipmentid == metSalesOrderShipmentLoadHeader.ShipmentId
        && metSalesOrderShipmentLoadHeader.RecId == dangerouseContract.parmRecId()
        exists join inventTable
        where inventTable.ItemId == metSalesOrderShipmentLoadLines.ItemId
        && inventTable.HMIMIndicator == NoYes::Yes
    {
        this.insertLineData(metSalesOrderShipmentLoadLines, metSalesOrderShipmentLoadHeader);
    }
    lineList.insertDatabase();

    select sum(ItemUnit)
        from metDangerousGoodsManifestLineTmp;

    sumOfItemUnit = metDangerousGoodsManifestLineTmp.ItemUnit;

    update_recordset metDangerousGoodsManifestLineTmp
        setting KGLAmount = sumOfItemUnit;

    select count(RecId)
        from metDangerousGoodsManifestLineTmp
        group by metDangerousGoodsManifestLineTmp.SalesOrder
        where metDangerousGoodsManifestLineTmp.Stop != 0;

    countOfStop = metDangerousGoodsManifestLineTmp.RecId;

    update_recordset metDangerousGoodsManifestTmp
        setting RouteStopNum = countOfStop;
}

/// <summary>
/// Insert into header table
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertHeaderData(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    InventLocation inventLocationFrom;

    inventLocationFrom = InventLocation::find(_metSalesOrderShipmentLoadHeader.Warehouse);

    METIndustryKeyTable metIndustryKeyTable;

    select firstonly CompanyName from metIndustryKeyTable
        where metIndustryKeyTable.IndustryKey == inventLocationFrom.METWHSubEntity;

   // metDangerousGoodsManifestTmp.MFGLogo = SysDocuBrandImages::getImage(inventLocationTo.METWHSubEntity);//Task226482

    metDangerousGoodsManifestTmp.IndustryKey = inventLocationFrom.METWHSubEntity; //Task 226480: CB272 - Branding details update - Reports
    metDangerousGoodsManifestTmp.CompanyName = metIndustryKeyTable.CompanyName;
    metDangerousGoodsManifestTmp.BranchName = inventLocationFrom.Name;
    metDangerousGoodsManifestTmp.BranchAddress = inventLocationFrom.address();
    metDangerousGoodsManifestTmp.Route = _metSalesOrderShipmentLoadHeader.Route;
    metDangerousGoodsManifestTmp.RouteStopNum = _metSalesOrderShipmentLoadHeader.RouteStopNum;
    metDangerousGoodsManifestTmp.AnyClass = this.checkClass(_metSalesOrderShipmentLoadHeader);
    metDangerousGoodsManifestTmp.UN = this.getUN(_metSalesOrderShipmentLoadHeader.ShipmentId);
    metDangerousGoodsManifestTmp.UnitOfMeasure =this.getUOM(_metSalesOrderShipmentLoadHeader.ShipmentId);

    NumberSequenceReference numberSequenceReference;

    numberSequenceReference = NumberSeqReference::findReference(extendedTypeNum(METDangerousGoodsManifestDocNum));

    if (numberSequenceReference.RecId)
    {
        metDangerousGoodsManifestTmp.ManifestDocumentNo = NumberSeq::newGetNum(numberSequenceReference).num();
    }

    CompanyInfo companyInfo;

    select firstonly METDocumentNum, METRevision, METRevisionDate
        from companyInfo
        where companyInfo.DataArea == curExt();

    metDangerousGoodsManifestTmp.DocumentNo = companyInfo.METDocumentNum;
    metDangerousGoodsManifestTmp.Revision = companyInfo.METRevision;
    metDangerousGoodsManifestTmp.RevisionDate = companyInfo.METRevisionDate;
    METDangerousGoodsManifestTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid; // dangerouseContract.parmBundleHeaderReportGuid();
    metDangerousGoodsManifestTmp.DangerousGoodsManifestHeaderGuidStr = headerReportGuid; // dangerouseContract.parmHeaderTableGuid();
    metDangerousGoodsManifestTmp.insert();

}

/// <summary>
/// Insert into Line tmp
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadLines">METSalesOrderShipmentLoadLines</param>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertLineData(METSalesOrderShipmentLoadLines _metSalesOrderShipmentLoadLines, METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    metDangerousGoodsManifestLineTmp.SalesOrder = _metSalesOrderShipmentLoadLines.ShipmentId;

    InventTransferTable inventTransferTable;
    InventLocation inventLocationTo;
    METInventLocation metInventLocationTo;
    CustTable custTable;
    HMIMItemMaterial hmimItemMaterial;
    METInventTable metInventTable;

    select firstonly custTable
        join RecId from metInventLocationTo
        where metInventLocationTo.InternalCustomer == custTable.AccountNum
        join Name from inventLocationTo
        where inventLocationTo.RecId == metInventLocationTo.InventLocation
        exists join inventTransferTable
        where inventLocationTo.InventLocationId == inventTransferTable.InventLocationIdTo
        && inventTransferTable.TransferId == _metSalesOrderShipmentLoadLines.OrderNum;

    metDangerousGoodsManifestLineTmp.CustAccount = custTable.AccountNum;
    metDangerousGoodsManifestLineTmp.CustName = inventLocationTo.Name;
    metDangerousGoodsManifestLineTmp.Stop = _metSalesOrderShipmentLoadHeader.RouteStopNum; 
    metDangerousGoodsManifestLineTmp.PG1 = this.checkClassForItem(_metSalesOrderShipmentLoadLines.ItemId);
    metDangerousGoodsManifestLineTmp.ItemId = _metSalesOrderShipmentLoadLines.ItemId;
    metDangerousGoodsManifestLineTmp.ItemDesc = InventTable::find(_metSalesOrderShipmentLoadLines.ItemId).itemName();

    select firstonly ClassCode, DivisionCode, IdentificationCode, PackingGroupCode, PackCode, UnitOfMeasure, LabelCode, MaterialDescription
        from hmimItemMaterial
        where hmimItemMaterial.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metDangerousGoodsManifestLineTmp.ClassCode = hmimItemMaterial.ClassCode;
    metDangerousGoodsManifestLineTmp.SubRisk = hmimItemMaterial.DivisionCode;
    metDangerousGoodsManifestLineTmp.UN = hmimItemMaterial.IdentificationCode;
    metDangerousGoodsManifestLineTmp.PackingGroupCode = hmimItemMaterial.PackingGroupCode;
    metDangerousGoodsManifestLineTmp.PackType = hmimItemMaterial.PackCode;
    metDangerousGoodsManifestLineTmp.UnitOfMeasure = hmimItemMaterial.UnitOfMeasure;

    select firstonly ItemSize from metInventTable
        where metInventTable.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metDangerousGoodsManifestLineTmp.ItemSize = metInventTable.ItemSize;
    metDangerousGoodsManifestLineTmp.Qty = _metSalesOrderShipmentLoadLines.Quantity;
    metDangerousGoodsManifestLineTmp.SalesOrder = _metSalesOrderShipmentLoadLines.ShipmentId;
    metDangerousGoodsManifestLineTmp.ItemUnit = _metSalesOrderShipmentLoadLines.Quantity * any2Int(metInventTable.ItemSize);
    metDangerousGoodsManifestLineTmp.Hazchem = hmimItemMaterial.LabelCode; 

    const str each = 'EA';

    metDangerousGoodsManifestLineTmp.ItemPack = (UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(InventTransferLine::find(_metSalesOrderShipmentLoadLines.InventTransId, _metSalesOrderShipmentLoadLines.LineNum).UnitId).RecId,
                                                UnitOfMeasure::findBySymbol(each).RecId,
                                                EcoResProduct::findByProductNumber(_metSalesOrderShipmentLoadLines.ItemId).RecId).Factor);
    metDangerousGoodsManifestLineTmp.Type = hmimItemMaterial.MaterialDescription;

    metDangerousGoodsManifestLineTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid; // dangerouseContract.parmBundleHeaderReportGuid();
    metDangerousGoodsManifestLineTmp.DangerousGoodsManifestHeaderGuidStr = headerReportGuid; // dangerouseContract.parmHeaderTableGuid();

    lineList.add(metDangerousGoodsManifestLineTmp);
}

/// <summary>
/// This method is used to check if item belongs to a Divison or not
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
/// <returns>boolean</returns>
public boolean checkClass(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    METSalesOrderShipmentLoadLines metSalesOrderShipmentLoadLines;
    HMIMItemMaterial hmIMItemMaterial;
    const str twoOne = '2.1';
    const str twoThree = '2.3';
    const str pgOne = 'PG1';

    select firstonly RecId from hmIMItemMaterial
        join metSalesOrderShipmentLoadLines
        where hmIMItemMaterial.ItemId == metSalesOrderShipmentLoadLines.ItemId
        && metSalesOrderShipmentLoadLines.ShipmentId == _metSalesOrderShipmentLoadHeader.ShipmentId
        && ( hmIMItemMaterial.DivisionCode == twoOne || hmIMItemMaterial.DivisionCode == twoThree || hmIMItemMaterial.DivisionCode == pgOne );

    if (hmIMItemMaterial)
    {
        return true;
    }

    return false;
}

/// <summary>
/// This method is used to check if item belongs to a Divison or not
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>boolean</returns>
public boolean checkClassForItem(ItemId _itemId)
{
    METSalesOrderShipmentLoadLines metSalesOrderShipmentLoadLines;
    HMIMItemMaterial hmIMItemMaterial;
    const str twoOne = '2.1';
    const str twoThree = '2.3';
    const str pgOne = 'PG1';

    select firstonly RecId from hmIMItemMaterial
        where hmIMItemMaterial.ItemId == _itemId
        && ( hmIMItemMaterial.DivisionCode == twoOne || hmIMItemMaterial.DivisionCode == twoThree || hmIMItemMaterial.DivisionCode == pgOne );

    if (hmIMItemMaterial)
    {
        return true;
    }

    return false;
}

/// <summary>
/// GET unique UN number
/// </summary>
/// <param name = "_shipmentId">MetShipmentId</param>
/// <returns>HMIMIdentificationCode</returns>
public HMIMIdentificationCode getUN(MetShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeaderLocal;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLinesLocal;
    HMIMItemMaterial                    hmimItemMaterialLocal;
    HMIMIdentificationCode              hmimIdentificationCode;

    while select IdentificationCode from hmimItemMaterialLocal
        group by IdentificationCode
        exists join metSalesOrderShipmentLoadLinesLocal
        where hmimItemMaterialLocal.ItemId == metSalesOrderShipmentLoadLinesLocal.ItemId
        exists join metSalesOrderShipmentLoadHeaderLocal
        where metSalesOrderShipmentLoadHeaderLocal.ShipmentId == metSalesOrderShipmentLoadLinesLocal.ShipmentId
        && metSalesOrderShipmentLoadHeaderLocal.ShipmentId == _shipmentId
    {
        hmimIdentificationCode += " " + hmimItemMaterialLocal.IdentificationCode;
    }

    return hmimIdentificationCode;
}

/// <summary>
/// GET unique UOM
/// </summary>
/// <param name = "_shipmentId">MetShipmentId</param>
/// <returns>UnitOfMeasureSymbol</returns>
public UnitOfMeasureSymbol getUOM(MetShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeaderLocal;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLinesLocal;
    HMIMItemMaterial                    hmimItemMaterialLocal;
    UnitOfMeasureSymbol                 unitOfMeasureSymbol;

    while select UnitOfMeasure from hmimItemMaterialLocal
        group by UnitOfMeasure
        exists join metSalesOrderShipmentLoadLinesLocal
        where hmimItemMaterialLocal.ItemId == metSalesOrderShipmentLoadLinesLocal.ItemId
        exists join metSalesOrderShipmentLoadHeaderLocal
        where metSalesOrderShipmentLoadHeaderLocal.ShipmentId == metSalesOrderShipmentLoadLinesLocal.ShipmentId
        && metSalesOrderShipmentLoadHeaderLocal.ShipmentId == _shipmentId
    {
        unitOfMeasureSymbol += " " + hmimItemMaterialLocal.UnitOfMeasure;
    }

    return unitOfMeasureSymbol;
}
